// #32: adaptar entradas; no filtrar pagos ni decidir abonos.
const input = $json;
const isForm = Object.prototype.hasOwnProperty.call(input, 'asunto') || Object.prototype.hasOwnProperty.call(input, 'cuerpo');
const text = value => typeof value === 'string' ? value.replace(/\r\n?/g, '\n') : '';
const asunto = text(isForm ? input.asunto : input.subject);
const cuerpo = text(isForm ? input.cuerpo : (input.textPlain || input.text));
const referencia = text(isForm ? input.referencia : (input.messageId || input.metadata?.['message-id'])).trim();
let motivo = '';
if (!asunto.trim() || !cuerpo.trim()) motivo = 'Falta asunto o cuerpo de texto plano; revisar la entrada';
else if (!referencia) motivo = 'Falta referencia de prueba o Message-ID del correo';
else if (cuerpo.length > 20000 || asunto.length > 998 || referencia.length > 300) motivo = 'Entrada demasiado larga; revisar sin procesar automáticamente';
return {json: {origen: isForm ? 'formulario' : 'imap', referencia, asunto, cuerpo, entrada_valida: !motivo, motivo}};

// #33: clasificar el aviso; la extracción de campos corresponde a #34.
if ($json.entrada_valida !== true) {
  return {json:{...$json,es_pago:false,ruta:'revisar',motivo:$json.motivo || 'Entrada inválida; revisar antes de continuar'}};
}
const texto = ($json.asunto + '\n' + $json.cuerpo).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const es_pago = /\b(?:has recibido un bizum|transferencia recibida|se ha abonado una transferencia)\b/.test(texto);
return {json:{...$json,es_pago,ruta:es_pago ? 'extraer' : 'ignorar',motivo:es_pago ? '' : 'No es un aviso de pago recibido reconocido'}};

// Code node, run once for each item. Only labelled payment fields leave for Groq.
const asunto = String($json.asunto ?? $json.subject ?? '').trim();
const cuerpo = String($json.cuerpo ?? $json.textPlain ?? $json.text ?? '').trim();
const referencia = String($json.referencia ?? $json.messageId ?? $json.metadata?.['message-id'] ?? '').trim();
const base = {referencia, asunto};
const revisar = motivo => ({json:{...base,ruta:'revisar',motivo}});
if (!cuerpo || cuerpo.length > 20000 || referencia.length > 300) return revisar('Correo vacío, demasiado largo o referencia inválida');
const text = asunto + '\n' + cuerpo;
if (!/(?:has recibido un bizum|transferencia (?:recibida|en su cuenta)|se ha abonado una transferencia)/i.test(text))
  return {json:{...base,ruta:'ignorar',motivo:'No es un aviso de pago reconocido'}};
if (!referencia) return revisar('Falta referencia única del correo; no registrar sin trazabilidad');
function field(label) {
  const matches = [...cuerpo.matchAll(new RegExp('^' + label + '[ \\t]*(?::|\\.{2,})[ \\t]*([^\\r\\n]*)','gmi'))];
  return matches.length === 1 ? matches[0][1].trim() : null;
}
const ordenante = field('Ordenante'), importeTexto = field('Importe'), concepto = field('Concepto');
if (!ordenante || importeTexto === null || concepto === null) return revisar('Faltan campos bancarios o hay campos duplicados');
const amount = importeTexto.match(/^(\d+(?:[.,]\d{1,2})?)\s*(EUR|€)$/i);
if (!amount || !Number.isFinite(Number(amount[1].replace(',','.'))) || Number(amount[1].replace(',','.')) <= 0)
  return revisar('Importe inválido o moneda distinta de EUR');
if (ordenante.length > 150 || concepto.length > 300) return revisar('Campos bancarios demasiado largos');
return {json:{...base,ruta:'extraer',fuente:{ordenante,importe:Number(amount[1].replace(',','.')),concepto},
  texto_ia:JSON.stringify({ordenante,importe:importeTexto,concepto})}};

const p = $('Preparar correo').item.json;
const revisar = motivo => ({json:{...p,ruta:'revisar',motivo}});
if ($json.error || $json.statusCode !== 200) throw new Error('Error técnico al extraer con Groq; revisar ejecución antes de continuar');
let data;
try {data=JSON.parse($json.body?.choices?.[0]?.message?.content);} catch {return revisar('La IA no devolvió un JSON válido');}
if (!data || Array.isArray(data) || Object.keys(data).sort().join(',') !== 'concepto,importe,ordenante' ||
 typeof data.ordenante !== 'string' || typeof data.concepto !== 'string' || typeof data.importe !== 'number' ||
 !Number.isFinite(data.importe) || data.importe <= 0) return revisar('Extracción incompleta o esquema inválido');
// Source comparison prevents prompt injection or hallucinations changing the payment.
if (data.ordenante.trim() !== p.fuente.ordenante || data.concepto.trim() !== p.fuente.concepto || data.importe !== p.fuente.importe)
 return revisar('La extracción no coincide con los campos del aviso bancario');
const ids = [...data.concepto.matchAll(/\bapartado\s*(?:n[º°o.]?\s*)?#?\s*(\d+)\b/gi)];
if (ids.length > 1) return revisar('El concepto contiene varios números de apartado');
const apartado_id = ids.length ? Number(ids[0][1]) : null;
if (apartado_id !== null && (!Number.isSafeInteger(apartado_id) || apartado_id <= 0)) return revisar('Número de apartado inválido');
// Short ASCII prefix avoids the SQL LIKE accent mismatch (LUC matches Lucía).
const first = data.ordenante.split(/\s+/)[0];
const prefix = (first.match(/^[a-z]+/i)?.[0] || '').slice(0,2);
const url_busqueda = apartado_id !== null ? 'http://tienda:8000/api/apartados/'+apartado_id :
 'http://tienda:8000/api/apartados?estado=activo&q='+encodeURIComponent(prefix);
return {json:{referencia:p.referencia,asunto:p.asunto,...data,apartado_id,url_busqueda,ruta:'buscar'}};

// #36: comparar identidad, concepto y reglas de negocio; no registrar.
const e = $('Validar extracción').item.json;
const revisar = (motivo, candidatos = []) => ({json:{...e,decision:'revisar',motivo_decision:motivo,candidatos}});
const status = Number($json.statusCode);
if (status === 401 || status >= 500) throw new Error('Error técnico en GET de apartados (HTTP ' + status + ')');
if (status === 404 && e.apartado_id !== null) return revisar('El apartado indicado en el concepto no existe; no se buscará otro automáticamente');
if (status !== 200) throw new Error('Error técnico en GET de apartados (HTTP ' + status + ')');
if (typeof e.concepto !== 'string' || !e.concepto.trim()) return revisar('El aviso no incluye concepto suficiente para identificar el apartado');
const body = $json.body;
const candidatos = Array.isArray(body) ? body : (body && typeof body === 'object' && !Array.isArray(body) ? [body] : []);
if (!candidatos.length) return revisar('La API no devolvió apartados candidatos');
if (e.apartado_id !== null && candidatos.some(a => Number(a.id) !== Number(e.apartado_id)))
  return revisar('La respuesta de API no coincide con el ID explícito del concepto', candidatos);
const norm = value => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const nameTokens = value => norm(value).split(/\s+/).filter(Boolean);
const payer = nameTokens(e.ordenante);
const matchesIdentity = a => {
  const customer = nameTokens(a.cliente);
  return customer.length > 0 && payer.length > 0 && customer.every(token => payer.some(p => p === token || (p.length === 1 && token.startsWith(p))));
};
const ignored = new Set(['abono','abonos','pago','pagos','bizum','transferencia','transferencias','apartado','apartados','numero','num','n','de','del','la','las','el','los','por','para','favor','mi','liquidar','liquida','pedido']);
const stem = token => token.length > 5 && token.endsWith('es') ? token.slice(0,-2) : (token.length > 4 && token.endsWith('s') ? token.slice(0,-1) : token);
const concept = nameTokens(e.concepto).filter(t => !ignored.has(t)).map(stem);
if (!concept.length) return revisar('El concepto no identifica ningún producto o referencia', candidatos);
const plausible = candidatos.filter(a => {
  if (e.apartado_id !== null && Number(a.id) !== Number(e.apartado_id)) return false;
  if (!matchesIdentity(a)) return false;
  const product = nameTokens(a.producto).map(stem);
  return concept.some(token => product.includes(token));
});
if (!plausible.length) return revisar('No hay un apartado que coincida claramente con ordenante y concepto', candidatos);
if (plausible.length !== 1) return revisar('Hay varios apartados posibles; se requiere revisión manual', plausible);
const apartado = plausible[0];
if (apartado.estado !== 'activo') return revisar('El apartado no está activo (' + String(apartado.estado ?? 'estado desconocido') + ')', plausible);
const limite = typeof apartado.fecha_limite === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(apartado.fecha_limite) ? apartado.fecha_limite : '';
const hoy = new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Madrid'}).format(new Date());
if (!limite) return revisar('La fecha límite del apartado no es válida', plausible);
if (hoy > limite) return revisar('El apartado está fuera de plazo desde ' + limite, plausible);
const importe = Number(e.importe), pendiente = Number(apartado.pendiente);
if (!Number.isFinite(importe) || importe <= 0 || !Number.isFinite(pendiente) || pendiente < 0)
  return revisar('El importe o el pendiente recibido de la API no es válido', plausible);
if (Math.round(importe * 100) > Math.round(pendiente * 100))
  return revisar('El importe supera lo pendiente (' + pendiente + ' €)', plausible);
return {json:{...e,decision:'registrar',motivo_decision:'Coincidencia única; apartado activo, en plazo y con saldo suficiente',apartado,candidatos:plausible}};

// #37: repetir las comprobaciones críticas antes de construir el POST.
const e = $json;
const revisar = motivo => ({json:{...e,ruta:'revisar',motivo_decision:motivo}});
if (e.decision !== 'registrar') return revisar('La decisión previa no autorizó el registro');
if (!e.apartado || !Number.isSafeInteger(Number(e.apartado.id)) || Number(e.apartado.id) <= 0)
  return revisar('Falta un ID de apartado válido');
if (e.apartado.estado !== 'activo') return revisar('El apartado ya no está activo');
const limite = typeof e.apartado.fecha_limite === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(e.apartado.fecha_limite) ? e.apartado.fecha_limite : '';
const hoy = new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Madrid'}).format(new Date());
if (!limite || hoy > limite) return revisar('El apartado está fuera de plazo o carece de fecha límite válida');
const importe = Number(e.importe), pendiente = Number(e.apartado.pendiente);
if (!Number.isFinite(importe) || importe <= 0 || !Number.isFinite(pendiente) || pendiente < 0 || Math.round(importe*100) > Math.round(pendiente*100))
  return revisar('El importe ya no cabe en el pendiente actual');
return {json:{...e,ruta:'enviar',apartado_id:Number(e.apartado.id),body:{importe,forma_pago:'bizum'}}};

// Un 422 es una regla de negocio; fallos técnicos deben alcanzar el Error Workflow 08.
const p = $('Preparar solicitud de abono (#37)').item.json;
if ($json.error || !Number.isInteger(Number($json.statusCode)))
  throw new Error('Error técnico de red al registrar el abono; no repetir automáticamente');
const status = Number($json.statusCode), body = $json.body;
if (status === 201) {
  if (!body || typeof body !== 'object' || Number(body.id) !== p.apartado_id)
    throw new Error('Respuesta 201 inesperada al registrar el abono; conciliar antes de reintentar');
  return {json:{...p,resultado_pago:'registrado',apartado_actualizado:body}};
}
if (status === 422) {
  const detail = typeof body?.detail === 'string' ? body.detail : 'La API rechazó el abono por una regla de negocio';
  return {json:{...p,ruta:'revisar',resultado_pago:'rechazado',motivo:detail}};
}
if (status === 404) return {json:{...p,ruta:'revisar',resultado_pago:'rechazado',motivo:'La API ya no encuentra el apartado; revisar antes de actuar'}};
throw new Error('Error técnico al registrar el abono (HTTP ' + status + '); no reintentar automáticamente');

// #38: avisar al equipo de la tienda con lo necesario para revisar; no reenviar el correo bancario.
const e = $json;
const safe = (value, limit = 300) => String(value ?? '').replace(/[\x00-\x1f\x7f]+/g,' ').replace(/\b(?:bcc|cc|to|from)\s*:\s*[^\s]+/gi,'[contenido omitido]').replace(/\s+/g,' ').trim().slice(0,limit);
let source = {};
try { source = $('Normalizar entrada de correo').item.json || {}; } catch { /* datos de entrada no disponibles */ }
const original = safe(source.asunto,1000) + ' ' + safe(source.cuerpo,20000);
const normalized = original.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const medio = safe(e.medio) || (normalized.includes('bizum') ? 'Bizum' : (normalized.includes('transferencia') ? 'Transferencia' : 'No identificado'));
const motivo = safe(e.motivo || e.motivo_decision || 'El pago requiere revisión manual');
const ordenante = safe(e.ordenante || 'No identificado');
const concepto = safe(e.concepto || 'No indicado');
const referencia = safe(e.referencia || 'No disponible',300);
const importe = Number(e.importe);
const importeTexto = Number.isFinite(importe) ? new Intl.NumberFormat('es-ES',{minimumFractionDigits:2,maximumFractionDigits:2}).format(importe) + ' €' : 'No identificado';
const candidates = Array.isArray(e.candidatos) ? e.candidatos : (e.apartado && typeof e.apartado === 'object' ? [e.apartado] : []);
const shown = candidates.slice(0,20);
const lines = shown.map(a => `- #${safe(a.id,20)} · ${safe(a.cliente || 'Cliente desconocido')} · ${safe(a.producto || 'Producto desconocido')}${a.talla ? ' · talla ' + safe(a.talla,30) : ''} · pendiente ${Number.isFinite(Number(a.pendiente)) ? new Intl.NumberFormat('es-ES',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(a.pendiente)) + ' €' : 'desconocido'} · límite ${safe(a.fecha_limite || 'desconocido',30)} · estado ${safe(a.estado || 'desconocido',30)}`).join('\n');
const candidatosTexto = lines || 'No hay candidatos disponibles.';
const adicionales = candidates.length > shown.length ? `\nHay ${candidates.length - shown.length} candidatos más; revisar la ejecución.` : '';
const text = `Hola, equipo de la tienda:\n\nHa llegado un pago que no he registrado. Revísalo y, si procede, regístralo manualmente en la app.\n\nMotivo: ${motivo}\nOrdenante: ${ordenante}\nImporte: ${importeTexto}\nMétodo indicado: ${medio}\nConcepto: ${concepto}\nReferencia: ${referencia}\n\nApartados candidatos:\n${candidatosTexto}${adicionales}\n\nNo vuelvas a registrar el pago hasta confirmar que no se haya aplicado ya.`;
return {json:{...e,asunto:'Pago recibido para revisar',text}};
